        "questionText": "A banker is reviewing the bank's current portfolio of outstanding loans and collected the following financial data (in thousands) on four companies that the bank has loaned money to.<div class='table-responsive'><table class='mcq-table'><thead><tr><th>Particulars</th><th>Company A</th><th>Company B</th><th>Company C</th><th>Company D</th></tr></thead><tbody><tr><td><strong>Earnings before interest and income taxes</strong></td><td>¥5,000</td><td>¥12,500</td><td>¥4,300</td><td>¥2,450</td></tr><tr><td><strong>Interest expense</strong></td><td>¥3,950</td><td>¥9,000</td><td>¥2,675</td><td>¥1,250</td></tr></tbody></table></div>On the basis of the information provided above, which company has the highest relative likelihood of defaulting on an outstanding loan?",
