        "id": 23,
        "questionText": "A summary of the Income Statement of Sahara Company is shown below.<div class='table-responsive'><table class='mcq-table'><thead><tr><th>Particulars</th><th>Amount</th></tr></thead><tbody><tr><td><strong>Sales</strong></td><td>$15,000,000</td></tr><tr><td><strong>Cost of sales</strong></td><td>9,000,000</td></tr><tr><td><strong>Operating expenses</strong></td><td>3,000,000</td></tr><tr><td><strong>Interest expense</strong></td><td>800,000</td></tr><tr><td><strong>Taxes</strong></td><td>880,000</td></tr><tr><td><strong>Net income</strong></td><td>$ 1,320,000</td></tr></tbody></table></div>Based on the above information, Sahara's degree of financial leverage is",
